func scoreWidth(score int) string {
	switch {
	case score >= 90:
		return "w-full"
	case score >= 75:
		return "w-3/4"
	case score >= 50:
		return "w-1/2"
	case score >= 25:
		return "w-1/4"
	case score > 0:
		return "w-1/12"
	}
	return "w-0"
}

